function renderInventory(){ $('#content').innerHTML=`<div class="welcome"><div><p class="eyebrow">TU DESPENSA, EN ORDEN</p><h1>Mi inventario</h1><p>Revisa, actualiza y decide qué aprovechar primero.</p></div><button class="primary" data-add>+ Agregar alimentos</button></div><div class="toolbar"><input id="search" aria-label="Buscar alimento" placeholder="Buscar en mi inventario…" value="${escapeHTML(query)}"><select id="filter" aria-label="Filtrar por urgencia"><option value="all">Todos los alimentos</option><option value="urgent">Usar primero</option><option value="fresh">Sin urgencia inmediata</option><option value="expired">Fecha superada</option><option value="pending">Sin fecha</option></select></div><p class="subtle">Las fechas de etiqueta y las revisiones sugeridas se distinguen en cada alimento. Una revisión sugerida no indica caducidad.</p><div class="grid" id="inventory-grid"></div>`;$('#filter').value=filter;renderItems();$('#search').oninput=e=>{query=e.target.value;renderItems();};$('#filter').onchange=e=>{filter=e.target.value;renderItems();};}
function renderItems(){const items=state.items.filter(i=>foodSearch(i.name,query)).filter(i=>{const d=daysLeft(i.date);return filter==='all'||filter==='urgent'&&(i.dateKind==='estimated'?d<=2:d>=0&&d<=2)||filter==='fresh'&&Number.isFinite(d)&&d>2||filter==='expired'&&d<0&&i.dateKind!=='estimated'||filter==='pending'&&!i.date;}).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));$('#inventory-grid').innerHTML=items.length?items.map(card).join(''):'<div class="empty"><h3>No hay alimentos para mostrar</h3><p>Prueba otra búsqueda o agrega tu primer alimento.</p><button class="secondary" data-add>Agregar alimento</button></div>';}
function openModal(title,body){$('#modal-kicker').textContent=title;$('#modal-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null;}}
function addOptions(){openModal('AGREGAR A MI COCINA','<h2>¿Qué hay en tu refri?</h2><p>Elige cómo quieres agregar tus alimentos.</p><div class="modal-actions"><button class="secondary" id="manual">Agregar manualmente</button><button class="primary" id="photo">Analizar fotos</button></div>');$('#manual').onclick=()=>editItem();$('#photo').onclick=photoFlow;}
function editItem(id){const item=state.items.find(i=>i.id===id);openModal(item?'EDITAR ALIMENTO':'REGISTRO MANUAL',`<h2>${item?'Actualiza tu alimento':'Agregar alimento'}</h2><form id="food-form"><label>Nombre<input id="food-name" required maxlength="100" value="${escapeHTML(item?.name||'')}" placeholder="Ej. Jitomate" list="food-suggestions"></label><datalist id="food-suggestions">${FOOD_CATALOG.map(f=>`<option value="${f.name}"></option>`).join('')}</datalist><div id="food-recognition" class="recognition" aria-live="polite"></div><div class="form-row"><label>Cantidad<input id="food-quantity" required maxlength="100" value="${escapeHTML(item?.quantity||'')}" placeholder="Ej. 3 piezas"></label><label>${item?.dateKind==='estimated'?'Revisión sugerida':'Fecha registrada'}<input id="food-date" type="date" value="${item?.date||''}"></label></div><p class="subtle">Puedes dejar la fecha pendiente. Confirma la cantidad y copia la fecha de la etiqueta. Puedes dejarla pendiente y completarla después.</p><div class="modal-actions"><button class="secondary" type="button" id="cancel-form">Cancelar</button><button class="primary" type="submit">Guardar alimento</button></div></form>`);$('#food-name').oninput=updateRecognition;updateRecognition();$('#cancel-form').onclick=closeModal;$('#food-form').onsubmit=e=>{e.preventDefault();const name=$('#food-name').value.trim(),quantity=$('#food-quantity').value.trim(),date=$('#food-date').value||null;if(!name||!quantity){toast('Completa nombre y cantidad.');return;}const data={id:item?.id||newId(),name,quantity,date,dateKind:item&&date===item.date?item.dateKind:'reference',dateEstimateNote:item&&date===item.date?item.dateEstimateNote:null,quantitySource:item&&quantity===item.quantity?item.quantitySource:'manual',emoji:resolveFood(name)?.emoji||(item?.name===name&&validFoodEmoji(item?.emoji)?item.emoji:'🍽️')};if(item)state.items=state.items.map(i=>i.id===id?data:i);else state.items.push(data);save();closeModal();render();toast('Alimento guardado.');};}
function updateRecognition(){const name=$('#food-name').value.trim(),food=resolveFood(name);$('#food-recognition').innerHTML=name?`<span class="recognition-emoji">${foodIcon(name)}</span><div>${food?`Asociado a <strong>${escapeHTML(food.name)}</strong>${food.method==='approximate'?' · coincidencia aproximada':''}`:'Alimento personalizado'}<small>${food?'Conservaremos el nombre que escribiste.':'Puedes guardarlo con este nombre.'}</small></div>`:'Escribe un alimento para ver su icono.';}
let photoSession=0,analysisController=null;
async function prepareImage(file){
 if(!['image/jpeg','image/png','image/webp','image/heic','image/heif'].includes(file.type)&&!(file.type===''&&/\.(jpe?g|png|webp|heic|heif)$/i.test(file.name||'')))throw new Error('Usa una foto JPG, PNG, WebP o una captura de la cámara.');
 if(file.size>20*1024*1024)throw new Error('Cada archivo debe pesar como máximo 20 MB.');
 const objectURL=URL.createObjectURL(file);
 try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('No se pudo abrir esta foto. Prueba tomarla de nuevo o elegir una imagen JPG.'));i.src=objectURL;});
 const scale=Math.min(1,2048/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.9);
 }finally{URL.revokeObjectURL(objectURL);}
}
async function photoFlow(){
 const session=++photoSession;let images=[],ready=false,selectionVersion=0,preparing=false,analyzing=false;
 openModal('AGREGAR DESDE UNA FOTO',`<h2>Fotografía tus alimentos.</h2><p>Sube hasta 3 fotos. Acerca la cámara a los alimentos y procura buena iluminación.</p><div class="upload-box photo-capture-box"><div class="photo-source-actions"><button type="button" class="primary photo-camera" id="take-photo"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 1-2h6l1 2h4a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2z"/><circle cx="12" cy="12" r="4"/></svg>Tomar foto</button><button type="button" class="secondary" id="choose-photos">Elegir de la galería</button></div><input id="camera-input" type="file" accept="image/*" capture="environment" aria-label="Tomar foto con la cámara trasera" hidden><input id="photo-input" type="file" multiple accept="image/jpeg,image/png,image/webp,image/heic,image/heif" aria-label="Elegir fotos de la galería" hidden><p class="photo-source-hint">En el celular, Tomar foto abre la cámara. También puedes elegir imágenes guardadas.</p><div id="photo-previews" class="photo-previews"></div><p id="photo-count" class="photo-count">0 de 3 fotos</p></div><p id="vision-status" class="photo-status" role="status" hidden></p><p class="subtle">Revisa los nombres antes de guardar. Puedes completar las cantidades y las fechas después.</p><details class="detector-coverage"><summary>Qué puede reconocer · 82 alimentos</summary><p>${KeeprDetection.coverage.map(escapeHTML).join(', ')}.</p><p>Si falta un alimento, puedes agregarlo manualmente.</p></details><div class="modal-actions"><button class="secondary" id="photo-manual">Agregar manualmente</button><button class="primary" id="analyze-photos" disabled>Analizar alimentos →</button></div>`);
 $('#photo-manual').onclick=()=>{photoSession++;analysisController?.abort();editItem();};
 const input=$('#photo-input'),camera=$('#camera-input'),cameraButton=$('#take-photo'),galleryButton=$('#choose-photos'),button=$('#analyze-photos'),status=$('#vision-status'),previews=$('#photo-previews');
 function controls(){status.hidden=!status.textContent;const blocked=preparing||analyzing;button.disabled=blocked||!ready||!images.length;cameraButton.disabled=galleryButton.disabled=blocked||images.length>=3;input.disabled=camera.disabled=blocked||images.length>=3;previews.querySelectorAll('button').forEach(b=>b.disabled=blocked);}
 function renderPhotos(){previews.innerHTML=images.map((src,i)=>`<figure class="selected-photo"><img src="${src}" alt="Foto ${i+1} seleccionada"><button type="button" data-remove-photo="${i}" aria-label="Quitar foto ${i+1}">×</button><figcaption>Foto ${i+1}</figcaption></figure>`).join('');$('#photo-count').textContent=`${images.length} de 3 fotos`;controls();}
 async function selectPhotos(files){if(!files.length)return;if(preparing||analyzing)return;if(images.length+files.length>3){status.textContent='Puedes agregar hasta 3 fotos. Quita una antes de agregar más.';status.hidden=false;return;}const version=++selectionVersion;preparing=true;controls();status.textContent='Preparando fotos…';status.hidden=false;try{const prepared=[];for(const file of files)prepared.push(await prepareImage(file));if(session!==photoSession||version!==selectionVersion)return;images.push(...prepared);renderPhotos();status.textContent=ready?`${images.length} foto(s) listas para analizar.`:'Fotos preparadas. Puedes agregarlas manualmente si el detector no está disponible.';}catch(e){if(session===photoSession&&version===selectionVersion)status.textContent=e.message;}finally{if(session===photoSession&&version===selectionVersion){preparing=false;controls();}}}
 input.onchange=()=>{const files=[...input.files];input.value='';return selectPhotos(files);};camera.onchange=()=>{const files=[...camera.files];camera.value='';return selectPhotos(files);};
 cameraButton.onclick=()=>camera.click();galleryButton.onclick=()=>input.click();
 previews.onclick=e=>{const target=e.target.closest('[data-remove-photo]');if(!target||preparing||analyzing)return;const index=Number(target.dataset.removePhoto);if(!Number.isInteger(index)||index<0||index>=images.length)return;images.splice(index,1);renderPhotos();status.textContent=images.length?`${images.length} foto(s) listas para analizar.`:'Toma una foto o elige imágenes de la galería.';};
 button.onclick=async()=>{if(!ready||!images.length||preparing||analyzing)return;analyzing=true;controls();button.textContent='Analizando…';status.textContent='Preparando análisis…';status.hidden=false;analysisController=new AbortController();const controller=analysisController;const timeout=setTimeout(()=>controller.abort(),300000);try{const data=await window.KeeprDetector.analyze(images,{signal:controller.signal,onProgress:message=>{if(session===photoSession)status.textContent=message;}});if(!Array.isArray(data.items)||!Array.isArray(data.notes))throw new Error('El detector devolvió una respuesta inválida.');if(session!==photoSession)return;reviewDetected(data,images);}catch(e){if(session===photoSession){status.textContent=e.name==='AbortError'?'El análisis se canceló o tardó demasiado. Prueba con una sola foto más cercana.':e.message;button.textContent='Reintentar análisis →';}}finally{clearTimeout(timeout);if(analysisController===controller)analysisController=null;if(session===photoSession){analyzing=false;controls();}}};
 ready=Boolean(window.KeeprDetector?.supported());status.textContent=ready?'':'No podemos analizar fotos en este navegador. Prueba con Safari o Chrome actualizado, o agrega tus alimentos manualmente.';status.hidden=ready;controls();
}
function reviewDetected(result,images){
 openModal('REVISAR RESULTADOS',`<h2>${result.items.length?`${result.items.length} alimento(s) para revisar`:'No se identificaron alimentos'}</h2><p>Todos los alimentos están seleccionados. Desmarca los que no quieras agregar y corrige los nombres si hace falta. Puedes dejar la cantidad y la fecha pendientes.</p><div class="photo-previews review-photos">${images.map((src,i)=>`<img src="${src}" alt="Foto analizada ${i+1}">`).join('')}</div><form id="review-form"><div id="detected-list"></div><button type="button" class="secondary" id="add-detected">+ Agregar alimento faltante</button><p id="review-error" role="alert"></p><div class="modal-actions"><button type="button" class="secondary" id="other-photos">Otra foto</button><button class="primary" type="submit">Guardar seleccionados</button></div></form>`);
 let next=0;const rows=[];
 function addRow(item){const row=document.createElement('section');row.className='detected-row';const index=next++;const uncertain=item.certainty==='uncertain';row.innerHTML=`<div class="detected-title"><label><input type="checkbox" class="detected-include" checked> Incluir alimento</label><span class="badge ${uncertain?'soon':''}">${uncertain?'Identidad por confirmar':item.quantitySource==='estimated'||item.dateKind==='estimated'?'Incluye estimaciones':'Sugerencia visual'}</span></div><label>Nombre<input class="detected-name" maxlength="100" value="${escapeHTML(item.name)}" required></label><small>Revisa el nombre antes de guardar.</small><div class="form-row"><label>Cantidad<input class="detected-quantity" maxlength="100" value="${escapeHTML(item.quantity||'')}" placeholder="Cantidad no identificada"></label><label>${item.dateKind==='estimated'?'Revisar antes de · sugerido':'Fecha de etiqueta'}<input type="date" class="detected-date" value="${escapeHTML(item.date||'')}"></label></div><small>${item.quantitySource==='estimated'?'Cantidad estimada: confirma o corrige.':item.quantitySource==='counted'?'Conteo visual por confirmar.':item.quantitySource==='label'?'Cantidad leída en la etiqueta.':'Cantidad pendiente de confirmar.'} ${item.dateKind==='estimated'?'Revisión sugerida para mañana; no es caducidad.':item.date?`Fecha leída: ${escapeHTML(item.dateText||'')} (${item.dateKind==='best_before'?'consumo preferente':'caducidad'}).`:'Fecha no legible o no visible; puedes dejarla pendiente.'}</small>`;row.dataset.index=index;$('#detected-list').append(row);const toggle=()=>row.querySelectorAll('input:not([type=checkbox])').forEach(i=>i.disabled=!row.querySelector('.detected-include').checked);row.querySelector('.detected-include').onchange=toggle;toggle();rows.push({row,item});}
 result.items.forEach(addRow);
 $('#add-detected').onclick=()=>{addRow({name:'',quantity:null,emoji:'🍽️',certainty:'clear'});rows.at(-1).row.querySelector('.detected-name').focus();};
 $('#other-photos').onclick=photoFlow;
 $('#review-form').onsubmit=e=>{e.preventDefault();const selected=rows.filter(({row})=>row.querySelector('.detected-include').checked);if(!selected.length){$('#review-error').textContent='Selecciona al menos un alimento o agrega uno manualmente.';return;}const newItems=[];const firstId=newId();for(const {row,item}of selected){const name=row.querySelector('.detected-name').value.trim(),quantity=row.querySelector('.detected-quantity').value.trim(),date=row.querySelector('.detected-date').value||null;if(!name){$('#review-error').textContent='Completa el nombre de los alimentos seleccionados.';return;}newItems.push({id:firstId+newItems.length,name,quantity:quantity||'Por confirmar',date,dateKind:date===item.date?item.dateKind:'reference',dateEstimateNote:date===item.date?item.dateEstimateNote:null,dateText:date===item.date?item.dateText:null,quantitySource:quantity===item.quantity?item.quantitySource:'manual',emoji:resolveFood(name)?.emoji||(name===item.name&&validFoodEmoji(item.emoji)?item.emoji:'🍽️')});}state.items.push(...newItems);save();closeModal();location.hash='inventario';render();toast(`${newItems.length} alimentos agregados al inventario.`);};
}
function showRecipe(id){const r=recipes.find(r=>r.id===id);if(!r)return;const m=matches(r),ready=m.length===r.needs.length;openModal('COCINA CON LO QUE TIENES',`<h2>${escapeHTML(r.name)}</h2><p>${r.time} minutos · ${r.servings||1} ${(r.servings||1)===1?'porción':'porciones'}</p><div class="ingredients">${r.needs.map((n,index)=>`<span class="${m.some(i=>sameFood(i.name,n))?'':'missing'}">${m.some(i=>sameFood(i.name,n))?'✓':'Falta:'} ${escapeHTML(n)}${r.amounts?' · '+escapeHTML(r.amounts[index]):''}</span>`).join('')}</div><p>${escapeHTML(r.pantry)}</p><ol class="steps">${r.steps.map(s=>`<li>${escapeHTML(s)}</li>`).join('')}</ol><p class="notice">Al terminar, podrás indicar cuánto usaste y conservar lo que quede en tu inventario.</p><div class="modal-actions"><button class="secondary" id="back-recipe">Volver</button><button class="primary" id="cook" ${ready?'':'disabled'}>Registrar preparación</button></div>`);$('#back-recipe').onclick=closeModal;$('#cook').onclick=()=>{
 const ingredients=matches(r);if(ingredients.length!==r.needs.length){toast('El inventario cambió. Revisa los ingredientes.');return;}
 openModal('ACTUALIZAR INVENTARIO',`<h2>¿Cuánto quedó?</h2><p>Conserva las cantidades que todavía tienes. Marca solo lo que terminaste.</p><form id="cook-form">${ingredients.map(i=>`<section class="consumption-row" data-id="${i.id}"><strong>${escapeHTML(i.name)}</strong><small>Antes: ${escapeHTML(i.quantity)}</small><label>Cantidad restante<input class="remaining" value="${escapeHTML(i.quantity)}" maxlength="100" required></label><label class="checkbox-label"><input class="finished" type="checkbox"> Se terminó por completo</label></section>`).join('')}<p id="cook-error" role="alert"></p><div class="modal-actions"><button type="button" class="secondary" id="cancel-cook">Cancelar</button><button type="submit" class="primary">Guardar consumo</button></div></form>`);
 document.querySelectorAll('.consumption-row').forEach(row=>row.querySelector('.finished').onchange=e=>{row.querySelector('.remaining').disabled=e.target.checked;});
 $('#cancel-cook').onclick=closeModal;$('#cook-form').onsubmit=e=>{e.preventDefault();try{const updates=[...document.querySelectorAll('.consumption-row')].map(row=>({id:Number(row.dataset.id),finished:row.querySelector('.finished').checked,remaining:row.querySelector('.remaining').value}));const next=Kitchen.consume(state.items,updates);state.items=next.items;state.consumed+=next.consumed;save();closeModal();render();toast('Cantidades actualizadas. ¡Buen provecho!');}catch(err){$('#cook-error').textContent=err.message;}};
 };}
function removeItem(id,consumed=false){const i=state.items.find(i=>i.id===id);if(!i)return;openModal(consumed?'MARCAR COMO CONSUMIDO':'ELIMINAR REGISTRO',`<h2>${consumed?'¿Ya lo aprovechaste?':'¿Retirar este alimento?'}</h2><p>Se quitará el registro completo: <strong>${escapeHTML(i.name)} · ${escapeHTML(i.quantity)}</strong>.</p>${consumed?'<p class="subtle">Si te queda una parte, cancela y edita la cantidad.</p>':''}<div class="modal-actions"><button class="secondary" id="cancel-remove">Cancelar</button><button class="primary" id="confirm-remove">${consumed?'Sí, lo consumí':'Eliminar'}</button></div>`);$('#cancel-remove').onclick=closeModal;$('#confirm-remove').onclick=()=>{state.items=state.items.filter(x=>x.id!==id);if(consumed)state.consumed++;save();closeModal();render();toast(consumed?'Consumo registrado.':'Alimento eliminado.');};}
$('#about').onclick=()=>{openModal('TU ESPACIO EN KEEPR','<h2>Una cocina mejor organizada.</h2><p>Tu inventario se guarda en este navegador. El recetario de Keepr funciona sin conexión una vez cargado. Fotografía tus compras, revisa los alimentos encontrados y descubre preparaciones con lo que tienes.</p><p>Las fechas sugeridas son recordatorios para revisar los alimentos, no fechas de caducidad. Los alimentos iniciales son ejemplos.</p><p class="subtle">Diseño con componentes adaptados de AstroWind · MIT · onWidget. Fotografía: Unsplash.</p><button id="reset" class="secondary">Restablecer ejemplo</button>');$('#reset').onclick=()=>{openModal('RESTABLECER EJEMPLO','<h2>¿Empezar de nuevo?</h2><p>Se eliminarán los cambios de este navegador y volverán los seis alimentos de ejemplo.</p><div class="modal-actions"><button class="secondary" id="no-reset">Cancelar</button><button class="primary" id="yes-reset">Restablecer</button></div>');$('#no-reset').onclick=closeModal;$('#yes-reset').onclick=()=>{state={items:seed(),consumed:0};generatedRecipes=[];generatedSignature='';try{localStorage.removeItem('keepr-recipes-v1');}catch{}query='';filter='all';save();closeModal();render();toast('Ejemplo restablecido.');};};};
$('#close-modal').onclick=closeModal;
$('#modal').addEventListener('close',()=>{photoSession++;if(analysisController){analysisController.abort();analysisController=null;}window.KeeprDetector?.release();if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null;}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-add'))addOptions();if(b.hasAttribute('data-scan'))photoFlow();if(b.dataset.go)location.hash=b.dataset.go;if(b.dataset.edit)editItem(Number(b.dataset.edit));if(b.dataset.consume)removeItem(Number(b.dataset.consume),true);if(b.dataset.remove)removeItem(Number(b.dataset.remove));if(b.dataset.recipe)showRecipe(Number(b.dataset.recipe));});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key==='keepr-v1')location.reload();});
render();
